def evaluar_rango(n):
    if 10 <= n <= 30:
        return 'Pertenece al rango 10 - 30'
    elif 31 <= n <= 60:
        return 'Pertenece al rango 31 - 60'
    elif 61 <= n <= 100:
        return 'Pertenece al rango 61 - 100'
    else:
        return 'El número no pertenece a ningún rango'

print(evaluar_rango(25))
print(evaluar_rango(45))
print(evaluar_rango(80))
print(evaluar_rango(5))

def obtener_dia(num):
    dias = {1: 'Lunes', 2: 'Martes', 3: 'Miércoles', 4: 'Jueves', 5: 'Viernes', 6: 'Sábado', 7: 'Domingo'}
    return dias.get(num, 'Número fuera de rango')

for i in [1, 4, 7, 9]:
    print(f'Día {i}: {obtener_dia(i)}')

def mayor_de_tres(a, b, c):
    if a >= b and a >= c:
        return a
    elif b >= c:
        return b
    else:
        return c

print('Mayor de (15, 42, 9):', mayor_de_tres(15, 42, 9))
print('Mayor de (88, 12, 50):', mayor_de_tres(88, 12, 50))

def es_primo(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

primos = [n for n in range(1, 20) if es_primo(n)]
print('Números primos entre 1 y 20:', primos)

def factorial(n):
    if n < 0:
        return None
    fact = 1
    for i in range(1, n + 1):
        fact *= i
    return fact

print('Factorial de 5:', factorial(5))
print('Factorial de 7:', factorial(7))

def promedio_lista(numeros):
    if not numeros:
        return 0.0
    return sum(numeros) / len(numeros)

notas = [75, 80, 90, 60, 100]
print('Notas:', notas)
print('Promedio:', promedio_lista(notas))

def contar_vocales(texto):
    vocales = 'aeiouAEIOU'
    return sum(1 for char in texto if char in vocales)

frase = 'Programación Orientada a Objetos'
print(f'Frase: "{frase}"')
print('Cantidad de vocales:', contar_vocales(frase))

def generar_tabla(n):
    for i in range(1, 11):
        print(f'{n} x {i:2d} = {n * i}')

print('Tabla del 7:')
generar_tabla(7)
